<template><div class="admin-content"><div class="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><h1 class="text-2xl font-black text-slate-900">Product Reviews</h1><p class="text-sm text-slate-500">Approve or hide verified customer reviews.</p></div><select v-model="filter" class="rounded-lg border border-slate-300 px-3 py-2"><option value="all">All reviews</option><option value="pending">Pending</option><option value="approved">Approved</option><option value="hidden">Hidden</option></select></div><div class="mt-6 space-y-4"><div v-if="loading" class="kc-panel p-6">Loading reviews…</div><div v-else-if="!rows.length" class="kc-panel p-6 text-slate-500">No reviews in this view.</div><article v-for="r in rows" :key="r.id" class="kc-panel p-5"><div class="flex flex-col gap-3 sm:flex-row sm:justify-between"><div><div class="text-amber-400">{{ '★'.repeat(r.rating)+'☆'.repeat(5-r.rating) }}</div><h2 class="font-black text-slate-900">{{ r.title || 'Customer review' }}</h2><NuxtLink :to="`/product/${r.products?.slug}`" class="text-sm font-bold text-blue-600">{{ r.products?.name }}</NuxtLink></div><span class="self-start rounded-full px-3 py-1 text-xs font-black uppercase" :class="r.status==='approved'?'bg-green-100 text-green-700':r.status==='hidden'?'bg-slate-200 text-slate-700':'bg-amber-100 text-amber-800'">{{ r.status }}</span></div><p class="mt-3 whitespace-pre-line text-sm text-slate-700">{{ r.review }}</p><div class="mt-4 flex flex-wrap gap-2"><button class="rounded-lg bg-green-600 px-3 py-2 text-sm font-bold text-white" @click="setStatus(r,'approved')">Approve</button><button class="rounded-lg bg-slate-700 px-3 py-2 text-sm font-bold text-white" @click="setStatus(r,'hidden')">Hide</button><button class="rounded-lg border border-amber-300 px-3 py-2 text-sm font-bold text-amber-700" @click="setStatus(r,'pending')">Pending</button><span class="ml-auto text-xs text-slate-400">Order #{{ r.order_id }} · Verified purchase</span></div></article></div></div></template>
<script setup lang="ts">definePageMeta({layout:'admin'}); const supabase=useSupabaseClient(); const rows=ref<any[]>([]),loading=ref(true),filter=ref('pending'); async function headers(){const {data:{session}}=await supabase.auth.getSession();return session?.access_token?{Authorization:`Bearer ${session.access_token}`}:{}} async function load(){loading.value=true;try{rows.value=await $fetch('/api/admin/reviews',{query:{status:filter.value},headers:await headers()})}finally{loading.value=false}} async function setStatus(r:any,status:string){await $fetch(`/api/admin/reviews/${r.id}`,{method:'PUT',headers:await headers(),body:{status}});await load()} watch(filter,load);onMounted(load);</script>
